uniform sampler2D iChannel0;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.y, iResolution.x);
    vec2 texUV = fragCoord / iResolution.xy;
    vec3 starfield = texture(iChannel0, texUV).rgb;
    float t = iTime * 2.0;
    float pulse = 0.35 + 0.07 * sin(t * 1.5);
    vec2 heartUV = uv / pulse;
    heartUV.y += 0.15;
    float x = heartUV.x;
    float y = heartUV.y;
    float d = x*x + pow(y - sqrt(abs(x)), 2.0);
    float heartMask = smoothstep(0.4, 0.38, d);
    float heartGlow = smoothstep(0.8, 0.0, d) * 0.4;
    vec3 heartCol = vec3(1.0, 0.1, 0.3) * (1.2 + 0.4 * sin(t));
    vec3 finalColor = mix(starfield, heartCol + starfield * 0.5, heartMask);
    finalColor += heartCol * heartGlow;
    fragColor = vec4(finalColor, 1.0);
}

let pitch = 0;
let rotation = 0;
let bobble = 0;

setHidePorts(true)

function setup() {
  createCanvas(400, 400, WEBGL);
  setPortCount(1, 0);
  setTitle("Transparent Pop Chedi-Man");
  noDrag();
  recv((data) => {
    pitch = data;
  });
}

function draw() {
  clear();
  orbitControl();
  scale(1.8);
  ambientLight(120, 80, 100);
  pointLight(255, 150, 200, 200, -200, 300);
  directionalLight(255, 200, 220, 0, 1, -1);
  rotateY(rotation);
  rotation += 0.01 + (pitch / 1000);
  bobble = lerp(bobble, map(pitch, 0, 127, 0, 0.5), 0.1);
  let headTilt = sin(frameCount * 0.15) * bobble;
  noStroke();
  push();
  fill(255, 105, 180, 150);
  translate(0, 60, 0);
  cylinder(35, 70);
  push();
  translate(-40, -10, 0);
  rotateZ(0.5);
  capsule(10, 30);
  pop();
  push();
  translate(40, -10, 0);
  rotateZ(-0.5);
  capsule(10, 30);
  pop();
  push();
  translate(0, 35, 0);
  fill(80, 20, 50, 180);
  cylinder(45, 10);
  pop();
  pop();
  push();
  translate(0, -30, 0);
  rotateX(headTilt);
  rotateZ(headTilt * 0.5);
  fill(255, 220, 230, 150);
  box(110, 100, 90);
  fill(40, 0, 20, 200);
  push();
  translate(-35, 0, 46);
  sphere(18);
  pop();
  push();
  translate(35, 0, 46);
  sphere(18);
  pop();
  push();
  translate(0, 15, 46);
  fill(255, 180, 200, 200);
  sphere(5);
  pop();
  push();
  translate(0, -60, 0);
  for (let i = 0; i < 5; i++) {
    push();
    translate(0, -i * 10, 0);
    let r = 30 - i * 6;
    if(i % 2 === 0) fill(255, 20, 147, 180); else fill(255, 192, 203, 180);
    cylinder(r, 8);
    pop();
  }
  translate(0, -50, 0);
  fill(255, 105, 180, 180);
  cone(5, 40);
  pop();
  pop();
}

function capsule(r, h) {
  cylinder(r, h);
  push();
  translate(0, h/2, 0);
  sphere(r);
  translate(0, -h, 0);
  sphere(r);
  pop();
}
